import{z as l,x as s,o as e,c as d,q as r,j as o,D as a,d as B,s as t,S as i,b as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"货币联盟的代价","description":"","frontmatter":{"title":"货币联盟的代价","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mh-monetary-union.md","filePath":"econ/mh-monetary-union.md","lastUpdated":1791413859000}'),p={name:"econ/mh-monetary-union.md"};function h(c,E,m,C,D,u){const A=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=r('<h1 id="货币联盟的代价" tabindex="-1">货币联盟的代价 <a class="header-anchor" href="#货币联盟的代价" aria-label="Permalink to &quot;货币联盟的代价&quot;">​</a></h1><div class="epigraph"><p>把铸币权放进同一个盒子容易，把调整的痛苦也放进去难；联盟的寿命取决于第二件事。</p><footer>—— 据 Mundell 1961；De Grauwe 整理</footer></div><p><a href="/econ/mh-hyperinflations">上一课</a>以财政结算收束了货币崩溃段；本课转向另一端：不锚金、而是彼此锚死的货币联盟。成员把汇率永久钉在平价一，等于自愿放弃贬值这个最便宜的调整工具。现代案例的危机机制，已有的<a href="/econ/eurozone-crisis">欧元区危机</a>与<a href="/econ/eurozone-debt-crisis">欧债危机</a>两课已写透；本课把 19 世纪两桩货币同盟摆进来做对照，看联盟的代价有哪些条款是历史上重复署名的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>联盟内部的实际汇率 \\(q = e + p^{*} - p\\)，其中 \\(e\\) 是成员间名义汇率。联盟把 \\(e\\) 钉死为零变动，不对称冲击来时，调整只剩两条慢路：实际贬值的分母——成员内部物价与工资的下行——以及跨成员的要素流动与财政转移。Mundell 的最优货币区判据问的就是：要素流动能不能补上汇率工具的空缺。</p><p><span class="marginnote">术语翻译：实际汇率 \\(q = e + p^{*} - p\\) 量的是两国货的真实贵贱——名义汇率 \\(e\\) 之外还要看两边物价 \\(p\\)。所谓「内部贬值」，就是在 \\(e\\) 被锁死时，靠把本国物价与工资压下来让本国货变便宜；效果与贬值同向，只是代价的形态从汇率变成失业与通缩。</span></p><p>缺口因此有两层。技术上：冲击吸收渠道够不够。政治上：联盟改变了成员的财政激励——自己的货币不再单独承受贬值与通胀惩罚，搭便车的诱惑随之而来。联盟易结难解，难解的正是第二层。</p><h3 id="两个-19-世纪标本" tabindex="-1">两个 19 世纪标本 <a class="header-anchor" href="#两个-19-世纪标本" aria-label="Permalink to &quot;两个 19 世纪标本&quot;">​</a></h3><p>拉丁货币同盟（1865）：法国、比利时、意大利、瑞士（希腊 1868 年加入）统一币制标准，五种面额的金银币跨境无限流通。锚是共同的，滥用也是共同的——意大利 1866 年暂停兑换，用不可兑纸券履行对盟友的义务，等于借同盟的铸币标准给自己的财政透支；1870 年代银价坠落又把共同锚掏空，1874 年限制自由铸银、1878 年停铸。斯堪的纳维亚货币同盟（1873–1931）：丹、瑞、挪货币互认平价流通，1905 年瑞典–挪威政治联合解体，货币同盟照常运转——直到 1931 年金本位终点才散伙。</p><p><span class="marginnote">斯堪的纳维亚样本常被误读成「货币一体可以先于政治一体」的成功案例：它确实跨过了 1905 年的政治离婚，但也说明没有财政维度的货币同盟，寿命不会超过它借来的锚——金一停，同盟当日就没了内容。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把联盟的存续写成三个条件的合取：共同锚可信、成员财政不搭便车、冲击有吸收渠道。历史样本各缺一角。拉丁同盟缺第二个条件：铸币标准公共化后，成员的赤字可以化作跨境流通的币材，纪律无人执行。斯堪的纳维亚缺第一条件的来源——锚全靠借金，自身无承诺能力。欧元区在头十年缺第二与第三：财政规则形同虚设，转移支付与银行联盟缺席；调整靠内部贬值，失业代付了本该由 \\(e\\) 支付的账——欧债危机课已给出银行–主权回路的完整机制。<a href="/econ/currency-crisis-models">货币危机模型</a>里的第一代逻辑在联盟内换了靶子：无处可投机的本币钉住消失，被挤兑的是成员的主权债。</p><p><span class="marginnote">数字实例：设联盟内本国物价比伙伴国高出 10%，而 \\(e\\) 已锁死。要恢复竞争力，只能靠国内物价工资相对下行约 10%；若一年最多压得动 2%，这条内部贬值之路要走五年——弹性汇率下一次 10% 的贬值当晚就能走完。慢，就是联盟给「调整」定下的价格。</span></p>',13)),(e(),o(i,null,{default:a(()=>[t(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHOCK%5B%22%E4%B8%8D%E5%AF%B9%E7%A7%B0%E5%86%B2%E5%87%BB%22%5D%20--%3E%20Q%5B%22%E5%90%8D%E4%B9%89%E6%B1%87%E7%8E%87%20e%20%E5%B7%B2%E9%94%81%E6%AD%BB%22%5D%0A%20%20Q%20--%3E%20CH%7B%22%E5%90%B8%E6%94%B6%E6%B8%A0%E9%81%93%3F%22%7D%0A%20%20CH%20--%3E%7C%E8%A6%81%E7%B4%A0%E6%B5%81%E5%8A%A8%E4%B8%8E%E8%B4%A2%E6%94%BF%E8%BD%AC%E7%A7%BB%7C%20ABSorb%5B%22%E8%B0%83%E6%95%B4%E7%94%B1%E8%81%94%E7%9B%9F%E5%88%86%E6%91%8A%22%5D%0A%20%20CH%20--%3E%7C%E6%97%A0%7C%20PDOWN%5B%22%E5%86%85%E9%83%A8%E8%B4%AC%E5%80%BC%EF%BC%9A%E7%89%A9%E4%BB%B7%E5%B7%A5%E8%B5%84%E4%B8%8B%E8%A1%8C%22%5D%0A%20%20PDOWN%20--%3E%20RECESS%5B%22%E5%A4%B1%E4%B8%9A%E6%89%BF%E6%8B%85%E8%B0%83%E6%95%B4%22%5D%0A%20%20FREE%5B%22%E6%88%90%E5%91%98%E8%B4%A2%E6%94%BF%E9%80%8F%E6%94%AF%22%5D%20--%3E%20ABUSE%5B%22%E6%BB%A5%E7%94%A8%E5%85%B1%E5%90%8C%E9%93%B8%E5%B8%81%E6%A0%87%E5%87%86%22%5D%0A%20%20ABUSE%20--%3E%20BREAK%5B%22%E9%94%9A%E8%A2%AB%E6%8E%8F%E7%A9%BA%E6%88%96%E5%90%8C%E7%9B%9F%E6%B6%A3%E6%95%A3%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=n("h2",{id:"机制",tabindex:"-1"},[B("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=n("p",null,"机制是激励的重新定价：钉住如金本位时，滥发的惩罚是自己货币被挤兑、金储备外流，日日可见；进了联盟，惩罚被推迟并公共化——某成员的超额赤字先是化作联盟内低成本融资，直到市场重新给主权风险定价。联盟因此不是汇率安排，而是一套财政纪律的托管制：要么有真实执行的共同规则，要么有真实的转移支付，二者必居其一。不这么做会错在哪：把拉丁同盟的死因记在银价上，就学不到「成员滥用铸币标准」这条可迁移的教训；把欧元当纯技术工程，就预测不了 2010 年之前那十年的财政搭便车。",-1)),(e(),o(i,null,{default:a(()=>[t(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20OWN%5B%22%E8%87%AA%E6%8C%81%E8%B4%A7%E5%B8%81%3A%20%E8%BF%87%E5%BA%A6%E8%B5%A4%E5%AD%97%22%5D%20--%3E%20RUN%5B%22%E6%9C%AC%E5%B8%81%E8%A2%AB%E6%8C%A4%E5%85%91%2C%20%E5%82%A8%E5%A4%87%E5%A4%96%E6%B5%81%22%5D%0A%20%20RUN%20--%3E%20TIGHT%5B%22%E6%83%A9%E7%BD%9A%E6%97%A5%E6%97%A5%E5%8F%AF%E8%A7%81%2C%20%E7%AB%8B%E5%88%BB%E6%94%B6%E6%95%9B%22%5D%0A%20%20UN%5B%22%E8%81%94%E7%9B%9F%E6%88%90%E5%91%98%3A%20%E8%BF%87%E5%BA%A6%E8%B5%A4%E5%AD%97%22%5D%20--%3E%20CHEAP%5B%22%E5%85%88%E5%90%83%E5%88%B0%E8%81%94%E7%9B%9F%E5%86%85%E4%BD%8E%E6%88%90%E6%9C%AC%E8%9E%8D%E8%B5%84%22%5D%0A%20%20CHEAP%20--%3E%20LATER%5B%22%E6%83%A9%E7%BD%9A%E6%8E%A8%E8%BF%9F%3A%20%E9%A3%8E%E9%99%A9%E5%85%AC%E5%85%B1%E5%8C%96%22%5D%0A%20%20LATER%20--%3E%20REPRICE%5B%22%E5%B8%82%E5%9C%BA%E9%87%8D%E6%96%B0%E5%AE%9A%E4%BB%B7%E6%88%90%E5%91%98%E4%B8%BB%E6%9D%83%E5%80%BA%22%5D%0A%20%20REPRICE%20--%3E%20CRISIS%5B%22%E6%AC%A7%E5%80%BA%E5%BC%8F%E9%93%B6%E8%A1%8C%E4%B8%8E%E4%B8%BB%E6%9D%83%E5%9B%9E%E8%B7%AF%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">常见误区：初学者容易把货币联盟当成汇率技术安排，以为「换一种货币单位」就是全部内容。实际上联盟拿走的是成员各自自带的货币惩罚机制，若没有共同财政规则或真实转移补位，搭便车只是时间问题——判断一个联盟的寿命，先看它的纪律托管是真是假。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只取联盟的一般机制：Target2、OMT 与银行联盟的细节在欧元区两课，锚的选择史在金本位与布雷顿森林诸课。OCA 理论只取 Mundell 的要素流动判据，McKinnon、Kenen 等扩展不展开。1931 年后浮动时代的锚改由各国自己做——那就是主干<a href="/econ/exchange-regimes">汇率制度</a>与<a href="/econ/inflation-targeting">通胀目标制</a>的疆域。</p><p>后课默认：「联盟」意味着平价锁定、纪律托管与转移渠道三者至少有其二。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>联盟锁死 \\(e\\)，调整只剩内部贬值、要素流动与转移支付三条慢路。</li><li>拉丁同盟死于成员对共同铸币标准的财政滥用；斯堪的纳维亚的寿命等于它借来的锚。</li><li>钉住的惩罚从挤兑自己货币变成推迟且公共化的主权风险重定价。</li><li>联盟是财政纪律的托管：真规则或真转移，必居其一。</li><li>出处：Mundell 1961；Eichengreen 1992；De Grauwe。</li></ul>',6))])}const F=l(p,[["render",h]]);export{_ as __pageData,F as default};
